const LEGACY_KEY="simple-step-db";
const Data=window.SimpleStepData;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const uid=Data.id,now=Data.now,dateKey=Data.dateKey;
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let db=Data.createEmptyDatabase(),activeDate=dateKey(),calendarMonth=dateKey().slice(0,7),lastToday=dateKey(),patrolHistoryWeek="",selectedProjectId="",selectedCategoryId="",categoryProjectCollapsed=new Set(),hierarchyExpanded=new Set(),routineCategoryExpanded=new Set();
const persist=()=>Data.repository.save(db),isLive=x=>!x.deletedAt,taskDate=t=>t.completedAt?.slice(0,10);
const itemOf=(kind,id)=>db[kind].find(x=>x.id===id);
const nameOf=(kind,id,includeDeleted=false)=>{const item=itemOf(kind,id);return item&&(includeDeleted||!item.deletedAt)?item.name:""};
const newestFirst=(a,b)=>String(b.createdAt||"").localeCompare(String(a.createdAt||""));
const newest=items=>[...items].sort(newestFirst);
const currentDay=()=>Data.businessDateKey(db.settings),currentWeek=()=>Data.weekKey(currentDay(),db.settings.weekStartsOn),currentMonth=()=>Data.monthKey(currentDay());
const isThisWeek=t=>t.weekStatusKey===currentWeek(),isThisMonth=t=>t.monthStatusKey===currentMonth();
const addDays=(key,amount)=>{const d=new Date(key+"T12:00:00");d.setDate(d.getDate()+amount);return dateKey(d)},dayDiff=(from,to)=>Math.round((new Date(to+"T12:00:00")-new Date(from+"T12:00:00"))/86400000);

// Shared rendering helpers keep every task view tied to the same task record.
function approved(t){return isLive(t)&&t.approvalStatus!=="pending"}
function options(kind,selected=""){return '<option value="">指定なし</option>'+db[kind].filter(isLive).map(x=>`<option value="${x.id}" ${x.id===selected?"selected":""}>${esc(x.name)}</option>`).join("")}
function projectOptions(categoryId="",selected=""){const projects=db.projects.filter(p=>isLive(p)&&(!categoryId||p.categoryId===categoryId));return '<option value="">指定なし</option>'+projects.map(p=>`<option value="${p.id}" ${p.id===selected?"selected":""}>${esc(p.name)}</option>`).join("")}
function metaFor(t){return [nameOf("categories",t.categoryId,true),nameOf("projects",t.projectId,true),isThisWeek(t)?"今週":"",isThisMonth(t)?"今月":"",t.source==="ai"?"AI登録":""].filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join("")}
function menuHtml(review=false){return `<div class="menu"><button class="more" data-action="menu" aria-label="操作">•••</button><div class="menu-panel" hidden><button data-action="edit-task">タスクカードを開く</button>${review?'<button data-action="change-date">完了日を直す</button>':""}<button class="danger" data-action="delete">削除する</button></div></div>`}
function taskHtml(t,{review=false,complete=false}={}){return `<article class="item" data-task-id="${t.id}">${complete?'<button class="complete" data-action="complete" title="完了">✓</button>':""}<div class="item-body"><p class="item-title">${esc(t.title)}</p><div class="meta">${metaFor(t)}</div></div>${menuHtml(review)}</article>`}
function journalHtml(j){const theme=nameOf("themes",j.themeId,true),category=nameOf("journalCategories",j.journalCategoryId,true),editable=j.journalKind==="one_line";return `<article class="item journal-item ${editable?"one-line-journal-item":""}" data-journal-id="${j.id}"><div><div class="meta"><span>${esc(j.entryDate)}</span><span>${new Date(j.createdAt).toLocaleTimeString("ja-JP",{hour:"2-digit",minute:"2-digit"})}</span>${theme?`<span>テーマ：${esc(theme)}</span>`:""}${category?`<span>一行日記：${esc(category)}</span>`:""}</div>${editable?`<button class="journal-text journal-edit-button" data-action="edit-one-line">${esc(j.text)}</button>`:`<p class="journal-text">${esc(j.text)}</p>`}</div><div class="menu"><button class="more" data-action="menu">•••</button><div class="menu-panel" hidden><button class="danger" data-action="delete-journal">削除する</button></div></div></article>`}
function taskActions(task){return `<div class="button-row"><button class="period-check ${isThisWeek(task)?"active":""}" data-action="star" data-period="week" title="今週">W</button><button class="period-check ${isThisMonth(task)?"active":""}" data-action="star" data-period="month" title="今月">M</button><button class="star ${task.todayDate===currentDay()?"active":""}" data-action="star" data-period="today" title="今日">${task.todayDate===currentDay()?"★":"☆"}</button>${menuHtml()}</div>`}
function openTaskRow(t){return `<article class="item" data-task-id="${t.id}"><button class="complete" data-action="complete" title="完了">✓</button><div class="item-body"><button class="task-title-button" data-action="edit-task">${esc(t.title)}</button><div class="meta">${metaFor(t)}</div></div>${taskActions(t)}</article>`}
function renderTasks(){const today=currentDay(),open=newest(db.tasks.filter(t=>approved(t)&&t.status!=="done")),starred=open.filter(t=>t.todayDate===today),backlog=open.filter(t=>t.todayDate!==today);$("#todayLabel").textContent=new Date(today+"T12:00:00").toLocaleDateString("ja-JP",{month:"long",day:"numeric",weekday:"short"});$("#todayCount").textContent=starred.length+"件";$("#backlogCount").textContent=backlog.length+"件";$("#todayTasks").innerHTML=starred.length?starred.map(openTaskRow).join(""):"<div class='empty'>星を付けたタスクが、ここに並びます。</div>";$("#backlogTasks").innerHTML=backlog.length?backlog.map(openTaskRow).join(""):"<div class='empty'>次にやることはありません。</div>"}
function todayExecution(){const active=db.routines.filter(r=>isLive(r)&&r.active),hasPlan=active.some(r=>Number.isInteger(r.dailyOrder));return hasPlan?active.filter(r=>Number.isInteger(r.dailyOrder)).sort((a,b)=>a.dailyOrder-b.dailyOrder):active.filter(r=>r.dailyState!=="skipped").sort((a,b)=>a.idealOrder-b.idealOrder)}
function renderTodayOverview(){const today=currentDay(),tasks=newest(db.tasks.filter(t=>approved(t)&&t.status!=="done"&&t.todayDate===today)),routines=todayExecution(),themes=newest(db.themes.filter(t=>isLive(t)&&t.active));$("#todayOverviewLabel").textContent=new Date(today+"T12:00:00").toLocaleDateString("ja-JP",{month:"long",day:"numeric",weekday:"short"});$("#todayOverviewTaskCount").textContent=tasks.length+"件";$("#todayOverviewTasks").innerHTML=tasks.length?tasks.map(openTaskRow).join(""):"<div class='empty compact-empty'>今日のタスクはありません。</div>";$("#todayRoutineCount").textContent=routines.filter(r=>r.dailyState==="completed").length+"/"+routines.length;$("#todayRoutineList").innerHTML=routines.length?routines.map((r,index)=>`<button class="today-routine-row ${r.dailyState==="completed"?"completed":""}" data-action="complete-routine" data-routine-id="${r.id}"><span class="routine-number">${r.dailyOrder||index+1}</span><strong>${esc(routineLabel(r))}</strong><span>${r.dailyState==="completed"?"✓":"完了"}</span></button>`).join(""):"<div class='empty compact-empty'>今日のルーティンはありません。</div>";$("#todayThemeList").innerHTML=themes.length?themes.map(t=>`<button type="button" class="today-theme-button" data-action="quick-journal" data-theme-id="${t.id}"><span>${esc(t.name)}</span><small>記録 ＋</small></button>`).join(""):"<div class='empty compact-empty'>継続テーマはありません。</div>"}
function renderPeriodTasks(){const open=newest(db.tasks.filter(t=>approved(t)&&t.status!=="done")),week=open.filter(isThisWeek),month=open.filter(isThisMonth),start=new Date(currentWeek()+"T12:00:00"),end=new Date(start);end.setDate(end.getDate()+6);$("#weekRange").textContent=`${start.toLocaleDateString("ja-JP",{month:"numeric",day:"numeric"})}～${end.toLocaleDateString("ja-JP",{month:"numeric",day:"numeric"})}`;$("#monthLabel").textContent=currentMonth().replace("-","年")+"月";$("#weekTaskList").innerHTML=week.length?week.map(openTaskRow).join(""):"<div class='empty'>今週のタスクはありません。</div>";$("#monthTaskList").innerHTML=month.length?month.map(openTaskRow).join(""):"<div class='empty'>今月のタスクはありません。</div>"}

// Page renderers read from db only; persistence stays in event and bridge handlers.
function renderJournals(){const selected=$("#journalDate").value||dateKey(),done=db.tasks.filter(t=>approved(t)&&t.status==="done"&&taskDate(t)===selected),rows=db.journals.filter(isLive).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,50),themes=db.themes.filter(t=>isLive(t)&&t.active),categories=db.journalCategories.filter(c=>isLive(c)&&c.active);$("#journalDoneCount").textContent=done.length+"件";$("#journalDoneTasks").innerHTML=done.length?done.map(t=>taskHtml(t)).join(""):"<div class='empty'>この日に完了したタスクはありません。</div>";$("#oneLineComposers").innerHTML=categories.length?categories.map(c=>`<form class="one-line-composer" data-journal-category-id="${c.id}"><label>${esc(c.name)}</label><input maxlength="500" required placeholder="一行で記録"><button class="secondary-button">記録</button></form>`).join(""):"<div class='empty compact-empty'>一行日記カテゴリはプロジェクトの登録・設定から追加できます。</div>";$("#themeComposers").innerHTML=themes.length?themes.map(t=>`<form class="theme-composer card" data-theme-id="${t.id}"><label>${esc(t.name)}<textarea rows="2" maxlength="2000" required placeholder="${esc(t.name)}について今日の記録"></textarea></label><div class="form-footer"><small>任意</small><button class="secondary-button">記録</button></div></form>`).join(""):"<div class='empty'>継続テーマはプロジェクトタブから追加できます。</div>";$("#journalTimeline").innerHTML=rows.length?rows.map(journalHtml).join(""):"<div class='empty'>最初の日記を書いてみましょう。</div>"}
function renderCalendar(){const [y,m]=calendarMonth.split("-").map(Number),first=new Date(y,m-1,1),days=new Date(y,m,0).getDate(),start=db.settings.weekStartsOn||0,names=["日","月","火","水","木","金","土"];$(".calendar-weekdays").innerHTML=Array.from({length:7},(_,i)=>`<span>${names[(start+i)%7]}</span>`).join("");$("#calendarTitle").textContent=`${y}年${m}月`;let html="";for(let i=0;i<(first.getDay()-start+7)%7;i++)html+='<span class="calendar-blank"></span>';for(let day=1;day<=days;day++){const key=`${calendarMonth}-${String(day).padStart(2,"0")}`,done=db.tasks.filter(t=>approved(t)&&t.status==="done"&&taskDate(t)===key).length,notes=db.journals.filter(j=>isLive(j)&&j.entryDate===key).length;html+=`<button class="calendar-day ${key===activeDate?"selected":""} ${key===currentDay()?"today":""}" data-date="${key}"><strong>${day}</strong><small>${done?"✓"+done:""} ${notes?"日"+notes:""}</small></button>`}$("#reviewCalendar").innerHTML=html}
function renderReview(){activeDate=$("#reviewDate").value||activeDate;$("#reviewDate").value=activeDate;calendarMonth=activeDate.slice(0,7);const selected=$("#reviewThemeFilter").value,current=selected;$("#reviewThemeFilter").innerHTML='<option value="">すべての日記</option><option value="__themed">テーマの記録だけ</option>'+db.themes.filter(isLive).map(t=>`<option value="${t.id}">${esc(t.name)}${t.active?"":"（終了）"}</option>`).join("");$("#reviewThemeFilter").value=current;const filter=$("#reviewThemeFilter").value,tasks=db.tasks.filter(t=>approved(t)&&t.status==="done"&&taskDate(t)===activeDate),journals=db.journals.filter(j=>isLive(j)&&j.entryDate===activeDate&&j.journalKind!=="one_line"&&(!filter||(filter==="__themed"?Boolean(j.themeId):j.themeId===filter))).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),oneLines=db.journals.filter(j=>isLive(j)&&j.entryDate===activeDate&&j.journalKind==="one_line"),groups=[...new Set(oneLines.map(j=>j.journalCategoryId))].map(id=>({id,name:nameOf("journalCategories",id,true)||"カテゴリなし",rows:oneLines.filter(j=>j.journalCategoryId===id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))}));renderCalendar();$("#reviewTasks").innerHTML=tasks.length?tasks.map(t=>taskHtml(t,{review:true})).join(""):"<div class='empty'>この日に完了したことはありません。</div>";$("#reviewJournals").innerHTML=journals.length?journals.map(journalHtml).join(""):"<div class='empty'>条件に合う日記はありません。</div>";$("#reviewOneLineJournals").innerHTML=groups.length?groups.map(group=>`<section class="one-line-review-group"><h3>${esc(group.name)}</h3><div class="stack">${group.rows.map(journalHtml).join("")}</div></section>`).join(""):"<div class='empty'>この日の一行日記はありません。</div>"}
function renderProjects(){for(const kind of ["categories","projects"]){const singular=kind==="categories"?"category":"project";$("#"+singular+"List").innerHTML=db[kind].filter(isLive).map(x=>`<span class="chip">${esc(x.name)}<button data-action="rename-class" data-kind="${kind}" data-id="${x.id}" title="名前を変更">✎</button><button data-action="delete-class" data-kind="${kind}" data-id="${x.id}" title="解除して削除">×</button></span>`).join("")||"<span class='meta'>まだありません</span>"}$("#themeList").innerHTML=db.themes.filter(isLive).map(t=>{const last=db.journals.filter(j=>isLive(j)&&j.themeId===t.id).sort((a,b)=>b.entryDate.localeCompare(a.entryDate))[0];return `<div class="theme-admin-row ${t.active?"":"ended"}"><div><strong>${esc(t.name)}</strong><small>${last?"最終記録 "+last.entryDate:"記録なし"}${t.active?"":"・終了中"}</small></div><div class="button-row"><button class="more" data-action="rename-theme" data-id="${t.id}">✎</button><button class="secondary-button" data-action="toggle-theme" data-id="${t.id}">${t.active?"終了":"再開"}</button></div></div>`}).join("")||"<div class='empty'>まだありません。</div>";const tasks=db.tasks.filter(t=>approved(t)&&t.status!=="done");$("#classificationCount").textContent=tasks.length+"件";$("#classificationTasks").innerHTML=tasks.length?tasks.map(t=>`<article class="classification-card card" data-task-id="${t.id}"><p class="item-title">${esc(t.title)}</p><div class="two-columns"><label>カテゴリ<select data-field="categoryId">${options("categories",t.categoryId)}</select></label><label>プロジェクト<select data-field="projectId">${projectOptions(t.categoryId,t.projectId)}</select></label></div></article>`).join(""):"<div class='empty'>整理する未完了タスクはありません。</div>"}
function renderRecurringRules(){const rows=db.recurringRules.filter(isLive);const labels={daily:"毎日",weekly:"毎週",monthly:"毎月",interval:"日ごと"};$("#recurringRuleList").innerHTML=rows.length?rows.map(rule=>{let schedule=labels[rule.frequency];if(rule.frequency==="weekly")schedule+=`（${rule.daysOfWeek.map(day=>"日月火水木金土"[day]).join("・")}）`;if(rule.frequency==="monthly")schedule+=` ${rule.dayOfMonth}日`;if(rule.frequency==="interval")schedule=`${rule.interval}日ごと`;return `<article class="item" data-rule-id="${rule.id}"><div class="item-body"><p class="item-title">${esc(rule.title)}</p><div class="meta"><span>${schedule}</span><span>${rule.startDate}から</span>${rule.active?"":"<span>停止中</span>"}</div></div><div class="button-row"><button class="more" data-action="edit-recurring">編集</button><button class="secondary-button" data-action="toggle-recurring">${rule.active?"停止":"再開"}</button></div></article>`}).join(""):"<div class='empty'>繰り返し設定はありません。</div>"}
function pendingTaskHtml(t){return `<article class="item" data-task-id="${t.id}"><div class="item-body"><p class="item-title">${esc(t.title)}</p><div class="meta"><span>新規タスク</span>${metaFor(t)}</div></div><div class="button-row"><button class="secondary-button" data-action="approve-pending">承認</button><button class="more danger" data-action="reject-pending">削除</button></div></article>`}
function changeValueLabel(field,value){if(field==="categoryId")return nameOf("categories",value)||"指定なし";if(field==="projectId")return nameOf("projects",value)||"指定なし";if(field==="priority")return ({none:"指定なし",low:"低",medium:"中",high:"高",urgent:"至急"})[value]||"指定なし";if(field==="estimateMinutes")return value?value+"分":"指定なし";if(["weekStatusKey","monthStatusKey"].includes(field))return value?"チェックあり":"チェックなし";return value||"指定なし"}
function pendingChangeHtml(c){const task=db.tasks.find(t=>t.id===c.taskId),labels={categoryId:"カテゴリ",projectId:"プロジェクト",description:"詳細",startDate:"とりかかり日",dueDate:"締め切り日",priority:"優先順位",estimateMinutes:"見積もり時間",weekStatusKey:"今週",monthStatusKey:"今月"},kind=labels[c.field]||c.field;return `<article class="item" data-change-id="${c.id}"><div class="item-body"><p class="item-title">${esc(task?.title||"対象タスクなし")}</p><div class="meta"><span>変更提案</span><span>${esc(kind)}：${esc(changeValueLabel(c.field,c.fromValue))} → ${esc(changeValueLabel(c.field,c.toValue))}</span></div></div><div class="button-row"><button class="secondary-button" data-action="approve-change">承認</button><button class="more danger" data-action="reject-change">削除</button></div></article>`}
function renderPending(){const tasks=db.tasks.filter(t=>isLive(t)&&t.approvalStatus==="pending"),changes=db.aiChanges.filter(c=>c.status==="pending");$("#inboxBadge").hidden=!(tasks.length+changes.length);$("#inboxBadge").textContent=tasks.length+changes.length;$("#approveAll").disabled=!(tasks.length+changes.length);$("#pendingItems").innerHTML=tasks.length+changes.length?[...tasks.map(pendingTaskHtml),...changes.map(pendingChangeHtml)].join(""):"<div class='empty'>未承認の項目はありません。</div>"}
function renderDeleted(){const rows=[...db.tasks.filter(x=>x.deletedAt).map(x=>({...x,kind:"task",label:x.title})),...db.journals.filter(x=>x.deletedAt).map(x=>({...x,kind:"journal",label:x.text}))].sort((a,b)=>b.deletedAt.localeCompare(a.deletedAt));$("#deletedItems").innerHTML=rows.length?rows.map(x=>`<article class="item" data-id="${x.id}" data-kind="${x.kind}"><div class="item-body"><p class="item-title">${esc(x.label)}</p><div class="meta"><span>${x.kind==="task"?"タスク":"日記"}</span></div></div><div class="button-row"><button class="secondary-button" data-action="restore">復元</button><button class="more danger" data-action="purge">完全削除</button></div></article>`).join(""):"<div class='empty'>削除済みの記録はありません。</div>";$("#purgeAllDeleted").disabled=!rows.length}
function renderSettings(){$("#weekStartsOn").value=String(db.settings.weekStartsOn);$("#dayRolloverTime").value=db.settings.dayRolloverTime}
function patrolPlaces(activeOnly=false){return db.patrolPlaces.filter(p=>isLive(p)&&(!activeOnly||p.active)).sort((a,b)=>(a.order||0)-(b.order||0))}
function patrolCheck(placeId,day){return db.patrolChecks.find(c=>c.patrolPlaceId===placeId&&c.businessDate===day)}
function patrolLastDay(place){const checked=db.patrolChecks.filter(c=>c.patrolPlaceId===place.id&&c.checked).sort((a,b)=>b.businessDate.localeCompare(a.businessDate))[0];return checked?.businessDate||Data.businessDateKey(db.settings,new Date(place.createdAt))}
function patrolStaleDays(place){return Math.max(0,dayDiff(patrolLastDay(place),currentDay()))}
function patrolTrackerHtml(start,places,editable=false){const today=currentDay(),days=Array.from({length:7},(_,i)=>addDays(start,i)),names=["日","月","火","水","木","金","土"];return `<div class="patrol-grid"><div class="patrol-grid-corner">巡回場所</div>${days.map(day=>{const d=new Date(day+"T12:00:00");return `<div class="patrol-day-head ${day===today?"today":""}"><span>${names[d.getDay()]}</span><small>${d.getDate()}</small></div>`}).join("")}${places.map(place=>{const stale=patrolStaleDays(place)>=3&&!patrolCheck(place.id,today)?.checked,createdDay=Data.businessDateKey(db.settings,new Date(place.createdAt));return `<div class="patrol-place-name ${stale?"stale":""}"><span>${esc(place.name)}</span><small>${stale?`最終${patrolStaleDays(place)}日前`:""}</small></div>${days.map(day=>{const check=patrolCheck(place.id,day),future=day>today,before=day<createdDay,state=check?.checked?"done":future||before?"future":"miss",late=Boolean(check?.checked&&check.backfilled),label=check?.checked?(late?"後から記録 ":"")+new Date(check.checkedAt).toLocaleTimeString("ja-JP",{hour:"2-digit",minute:"2-digit"}):before?"登録前":future?"未来":"未確認",content=state==="done"?(late?"✓*":"✓"):state==="miss"?"○":"·",classes=`patrol-cell ${state} ${late?"backfilled":""} ${day===today?"today":""}`;return editable&&!future&&!before?`<button type="button" class="${classes}" data-action="toggle-patrol-date" data-id="${place.id}" data-day="${day}" title="${esc(day+" "+label)}">${content}</button>`:`<div class="${classes}" title="${esc(day+" "+label)}">${content}</div>`}).join("")}`}).join("")}</div>`}
function renderPatrol(){const today=currentDay(),active=patrolPlaces(true),done=active.filter(place=>patrolCheck(place.id,today)?.checked).length;$("#patrolTodayCount").textContent=`${done}/${active.length}`;$("#patrolTodayList").innerHTML=active.length?active.map(place=>{const check=patrolCheck(place.id,today),checked=check?.checked,stale=patrolStaleDays(place)>=3&&!checked;return `<button class="patrol-check-row ${checked?"checked":""} ${stale?"stale":""}" data-action="toggle-patrol" data-id="${place.id}"><span class="patrol-check-mark">${checked?"✓":""}</span><strong>${esc(place.name)}</strong><small>${checked?new Date(check.checkedAt).toLocaleTimeString("ja-JP",{hour:"2-digit",minute:"2-digit"}):stale?`最終${patrolStaleDays(place)}日前`:"未確認"}</small></button>`}).join(""):"<div class='empty compact-empty'>巡回管理から巡回場所を追加できます。</div>";$("#patrolWeekTracker").innerHTML=active.length?patrolTrackerHtml(currentWeek(),active):"<div class='empty compact-empty'>巡回場所はまだありません。</div>"}
function renderPatrolManage(){if(!patrolHistoryWeek)patrolHistoryWeek=currentWeek();const places=patrolPlaces(),start=patrolHistoryWeek,end=addDays(start,6);$("#patrolHistoryTitle").textContent=`${Number(start.slice(5,7))}/${Number(start.slice(8))}～${Number(end.slice(5,7))}/${Number(end.slice(8))}`;$("#nextPatrolWeek").disabled=start>=currentWeek();$("#patrolHistoryTracker").innerHTML=places.length?patrolTrackerHtml(start,places,true)+"<small class='patrol-backfill-note'>* 後から記録したチェック</small>":"<div class='empty compact-empty'>巡回場所はまだありません。</div>";$("#patrolPlaceList").innerHTML=places.length?places.map((place,index)=>{const hasHistory=db.patrolChecks.some(c=>c.patrolPlaceId===place.id);return `<article class="item patrol-place-admin ${place.active?"":"ended"}" data-patrol-id="${place.id}"><div class="item-body"><p class="item-title">${esc(place.name)}</p><div class="meta"><span>${place.active?"使用中":"使用終了"}</span></div></div><div class="button-row"><button class="more" data-action="move-patrol-up" ${index===0?"disabled":""}>↑</button><button class="more" data-action="move-patrol-down" ${index===places.length-1?"disabled":""}>↓</button><button class="more" data-action="rename-patrol">編集</button><button class="secondary-button" data-action="toggle-patrol-active">${place.active?"終了":"再開"}</button>${hasHistory?"":'<button class="more danger" data-action="delete-patrol">削除</button>'}</div></article>`}).join(""):"<div class='empty'>巡回場所はまだありません。</div>"}
function sortRecordsNewest(){for(const kind of ["tasks","journals","categories","projects","themes","recurringRules","routines","aiChanges"]){db[kind].sort(newestFirst)}}
function moveTaskSaveButtonToTop(){const heading=$("#taskEditor .dialog-heading"),save=$("#saveTaskEditor"),close=heading?.querySelector('[value="cancel"]');if(heading&&save&&close&&save.parentElement!==heading)heading.insertBefore(save,close)}
