function setupHierarchyManagement(){const manage=$("#projectManageView");if(!manage||$("#hierarchyManager"))return;manage.querySelectorAll(":scope>.settings-grid>.card:nth-child(-n+2)").forEach(card=>card.hidden=true);const card=document.createElement("section");card.id="hierarchyManager";card.className="card hierarchy-manager";card.innerHTML='<h2>カテゴリ・プロジェクト登録</h2><form id="hierarchyForm" class="composer"><input id="hierarchyProjectId" type="hidden"><label>親カテゴリ<div class="inline-form"><select id="hierarchyCategorySelect"></select><input id="hierarchyCategoryNew" maxlength="80" placeholder="新しいカテゴリ名" hidden><button type="button" class="secondary-button" data-action="toggle-new-category">＋新規</button></div></label><label>子プロジェクト（空欄ならカテゴリのみ登録）<input id="hierarchyProjectName" maxlength="100" placeholder="プロジェクト名"></label><div class="form-footer"><button type="button" class="more" data-action="cancel-hierarchy-edit" hidden>取消</button><button class="primary-button" id="hierarchySave">登録</button></div></form><div id="hierarchyAdminList" class="stack"></div>';manage.prepend(card);card.onclick=e=>{const action=e.target.dataset.action;if(action==="toggle-new-category"){const input=$("#hierarchyCategoryNew"),select=$("#hierarchyCategorySelect"),usingNew=input.hidden;input.hidden=!usingNew;select.hidden=usingNew;e.target.textContent=usingNew?"既存から選ぶ":"＋新規"}if(action==="cancel-hierarchy-edit"){e.preventDefault();$("#hierarchyProjectId").value="";$("#hierarchyProjectName").value="";$("#hierarchySave").textContent="登録";e.target.hidden=true}if(action==="edit-project-parent"){const project=db.projects.find(p=>p.id===e.target.dataset.id);if(project){$("#hierarchyProjectId").value=project.id;$("#hierarchyProjectName").value=project.name;$("#hierarchyCategorySelect").value=project.categoryId||"";$("#hierarchyCategoryNew").hidden=true;$("#hierarchyCategorySelect").hidden=false;$("#hierarchySave").textContent="変更を保存";card.querySelector('[data-action="cancel-hierarchy-edit"]').hidden=false;card.scrollIntoView({behavior:"smooth"})}}};$("#hierarchyForm").onsubmit=async e=>{e.preventDefault();const editId=$("#hierarchyProjectId").value,newName=$("#hierarchyCategoryNew").hidden?"":$("#hierarchyCategoryNew").value.trim(),categoryId=newName?ensureName("categories",newName):$("#hierarchyCategorySelect").value,projectName=$("#hierarchyProjectName").value.trim();if(editId){const project=db.projects.find(p=>p.id===editId);if(project&&projectName){project.name=projectName;project.categoryId=categoryId;db.tasks.filter(t=>t.projectId===project.id).forEach(t=>Data.updateTask(t,{categoryId},"user"))}}else if(projectName&&!db.projects.some(p=>isLive(p)&&p.name.toLowerCase()===projectName.toLowerCase()))db.projects.push({id:uid(),name:projectName,categoryId,createdAt:now(),deletedAt:null});else if(!projectName&&!newName)return;e.target.reset();$("#hierarchyProjectId").value="";$("#hierarchyCategoryNew").hidden=true;$("#hierarchyCategorySelect").hidden=false;$("#hierarchySave").textContent="登録";card.querySelector('[data-action="cancel-hierarchy-edit"]').hidden=true;await persist();renderAll()}}
