function setupManageAccordions(){const manage=$("#projectManageView");if(!manage||$("#manageAccordions"))return;const holder=document.createElement("div");holder.id="manageAccordions";holder.className="manage-accordions";const oneLine=document.createElement("section");oneLine.id="journalCategoryManager";oneLine.className="card";oneLine.innerHTML='<h2>一行日記カテゴリ</h2><form id="journalCategoryForm" class="inline-form"><input id="journalCategoryName" maxlength="80" required placeholder="例：子供日記"><button class="secondary-button">追加</button></form><div id="journalCategoryList" class="theme-admin-list"></div>';const hierarchy=$("#hierarchyManager"),theme=$("#themeList")?.closest(".card"),recurring=$("#addRecurringRule")?.closest(".task-section"),classification=$("#classificationTasks")?.closest(".task-section"),items=[[hierarchy,"カテゴリ・プロジェクト"],[theme,"継続テーマ"],[oneLine,"一行日記カテゴリ"],[recurring,"繰り返し設定"],[classification,"タスクの分類"]];for(const [node,title] of items){if(!node)continue;const details=document.createElement("details"),summary=document.createElement("summary"),body=document.createElement("div"),close=document.createElement("button");details.className="manage-accordion";summary.textContent=title;body.className="manage-panel-body";close.type="button";close.className="secondary-button manage-close";close.dataset.action="close-manage-section";close.textContent="閉じる";body.append(node,close);details.append(summary,body);holder.append(details)}manage.querySelector(":scope>.settings-grid")?.setAttribute("hidden","");manage.prepend(holder)}
