function setupRoutinePage(){if($("#routines"))return;const nav=$("#mainNav"),captureButton=nav.querySelector('[data-page="capture"]'),button=document.createElement("button"),page=document.createElement("section");button.className="nav-button";button.dataset.page="routines";button.textContent="ルーティン";nav.insertBefore(button,captureButton.nextSibling);page.id="routines";page.className="page";page.innerHTML='<header class="page-heading"><div><p class="eyebrow">ルーティン</p><h1>今日やる順番を決める</h1></div><span id="routineDate" class="count"></span></header><div class="project-subnav routine-subnav"><button class="project-view-button active" data-routine-view="execute">実行する</button><button class="project-view-button" data-routine-view="today">今日の順番</button><button class="project-view-button" data-routine-view="manage">登録・設定</button></div><div id="routineExecuteView"></div><div id="routineTodayView" hidden></div><div id="routineManageView" hidden><form id="routineForm" class="composer card"><label>ルーティン名<input id="routineTitle" maxlength="120" required placeholder="例：今日の予定を確認する"></label><label>説明（任意）<textarea id="routineDescription" rows="2" maxlength="1000"></textarea></label><div class="form-footer"><small>理想の順番で一覧に追加します。</small><button class="primary-button">追加</button></div></form><form id="routineCategoryForm" class="composer card"><label>カテゴリをルーティンに追加<select id="routineCategorySelect"></select></label><div class="form-footer"><small>カテゴリ本体やタスクは削除されません。</small><button id="routineCategoryAdd" class="primary-button">追加</button></div></form><div id="routineManageList" class="stack"></div></div>';$("main").append(page)}
function reconcileRoutines(){const today=currentDay();for(const routine of db.routines){if(routine.dailyDate===today)continue;routine.dailyDate=today;routine.dailyState="undecided";routine.dailyOrder=null}}
function routineLabel(routine){return routine.itemType==="category"?(nameOf("categories",routine.categoryId,true)||routine.title):routine.title}
function routineCategoryContent(routine){if(routine.itemType!=="category")return "";const projects=newest(db.projects.filter(p=>isLive(p)&&p.categoryId===routine.categoryId)),direct=newest(db.tasks.filter(t=>approved(t)&&t.status!=="done"&&!t.projectId&&t.categoryId===routine.categoryId));const rows=tasks=>tasks.length?`<div class="stack">${tasks.map(openTaskRow).join("")}</div>`:'<small class="meta">未完了タスクなし</small>';return `<div class="routine-category-content"><section><strong>プロジェクトなし</strong>${rows(direct)}</section>${projects.map(p=>`<section><strong>${esc(p.name)}</strong>${rows(newest(db.tasks.filter(t=>approved(t)&&t.status!=="done"&&t.projectId===p.id)))}</section>`).join("")}</div>`}
function routineCard(routine){const selected=Number.isInteger(routine.dailyOrder),completed=routine.dailyState==="completed",skipped=routine.dailyState==="skipped",badge=selected?`<span class="routine-number">${routine.dailyOrder}</span>`:'<span class="routine-number empty-number"></span>',category=routine.itemType==="category",open=routineCategoryExpanded.has(routine.id);return `<article class="routine-card card ${selected?"selected":""} ${completed?"completed":""} ${skipped?"skipped":""}" data-routine-id="${routine.id}"><button class="routine-select" data-action="select-routine">${badge}<span><strong>${esc(routineLabel(routine))}</strong>${routine.description?`<small>${esc(routine.description)}</small>`:""}</span></button><button class="routine-skip ${skipped?"active":""}" data-action="skip-routine">${skipped?"やらない ✓":"今日はやらない"}</button>${category?`<button class="routine-details" data-action="toggle-routine-category">${open?"内容を隠す":"内容を見る"}</button>${open?routineCategoryContent(routine):""}`:""}</article>`}
function renderRoutines(){const today=currentDay(),routines=db.routines.filter(r=>isLive(r)&&r.active).sort((a,b)=>a.idealOrder-b.idealOrder),todayTasks=newest(db.tasks.filter(t=>approved(t)&&t.status!=="done"&&(t.todayDate===today||t.dueDate===today||t.startDate===today))),selected=routines.filter(r=>r.dailyState==="selected").sort((a,b)=>a.dailyOrder-b.dailyOrder);$("#routineDate").textContent=new Date(today+"T12:00:00").toLocaleDateString("ja-JP",{month:"long",day:"numeric",weekday:"short"});$("#routineTodayView").innerHTML=`<section class="routine-task-reference"><div class="section-title"><h2>今日の予定・タスク</h2><span class="count">${todayTasks.length}件</span></div><div class="routine-task-chips">${todayTasks.length?todayTasks.map(t=>`<span>${esc(t.title)}</span>`).join(""):"<span class='meta'>今日指定のタスクはありません。</span>"}</div></section><div class="section-title"><div><h2>理想のルーティン</h2><small>やる順番にカードをタップしてください。</small></div><button class="more" data-action="clear-routine-plan" ${selected.length?"":"disabled"}>選択を解除</button></div><div class="routine-list">${routines.length?routines.map(routineCard).join(""):'<div class="empty">ルーティンはまだありません。登録・設定から追加できます。</div>'}</div>`;$("#routineManageList").innerHTML=routines.length?routines.map((r,index)=>`<article class="item" data-routine-id="${r.id}"><div class="item-body"><p class="item-title">${esc(r.title)}</p><div class="meta"><span>理想順 ${index+1}</span></div></div><div class="button-row"><button class="more" data-action="move-routine-up" ${index===0?"disabled":""}>↑</button><button class="more" data-action="move-routine-down" ${index===routines.length-1?"disabled":""}>↓</button><button class="more" data-action="edit-routine">編集</button><button class="more danger" data-action="delete-routine">削除</button></div></article>`).join(""):'<div class="empty">ルーティンはまだありません。</div>'}
function renderRoutineCategoryPicker(){const select=$("#routineCategorySelect"),add=$("#routineCategoryAdd");if(!select)return;const used=new Set(db.routines.filter(r=>isLive(r)&&r.itemType==="category").map(r=>r.categoryId)),available=newest(db.categories.filter(c=>isLive(c)&&!used.has(c.id)));select.innerHTML=available.length?available.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join(""):'<option value="">追加できるカテゴリはありません</option>';add.disabled=!available.length;for(const row of $$("#routineManageList [data-routine-id]")){const routine=db.routines.find(r=>r.id===row.dataset.routineId);if(!routine||routine.itemType!=="category")continue;row.querySelector(".item-title").textContent=routineLabel(routine);row.querySelector('[data-action="edit-routine"]')?.remove()}}
function renderRoutineExecution(){const view=$("#routineExecuteView");if(!view)return;const active=db.routines.filter(r=>isLive(r)&&r.active),hasPlan=active.some(r=>Number.isInteger(r.dailyOrder)),execution=todayExecution(),done=execution.filter(r=>r.dailyState==="completed").length;view.innerHTML=`<div class="section-title"><div><h2>今日の実行順</h2><small>${hasPlan?"今日指定した順番です。":"理想の順番を表示しています。"}</small></div><span class="count">${done}/${execution.length} 完了</span></div><div class="routine-execute-list">${execution.length?execution.map((r,index)=>`<article class="routine-execute-wrap"><button class="routine-execute-card card ${r.dailyState==="completed"?"completed":""}" data-action="complete-routine" data-routine-id="${r.id}"><span class="routine-number">${r.dailyOrder||index+1}</span><span><strong>${esc(routineLabel(r))}</strong>${r.description?`<small>${esc(r.description)}</small>`:""}</span><span class="routine-complete-mark">${r.dailyState==="completed"?"✓ 完了":"タップで完了"}</span></button>${r.itemType==="category"?routineCategoryContent(r):""}</article>`).join(""):'<div class="empty">今日実行するルーティンはありません。</div>'}</div>`;const clear=$("#routineTodayView [data-action='clear-routine-plan']");if(clear)clear.disabled=!hasPlan}
function showRoutineView(view="execute"){$("#routineTodayView").hidden=view!=="today";$("#routineExecuteView").hidden=view!=="execute";$("#routineManageView").hidden=view!=="manage";$$('[data-routine-view]').forEach(item=>item.classList.toggle("active",item.dataset.routineView===view))}
function renderAll(){sortRecordsNewest();moveTaskSaveButtonToTop();setupProjectViews();setupRoutinePage();setupHierarchyManagement();setupManageAccordions();reconcileRoutines();renderTasks();renderPeriodTasks();renderJournals();renderReview();includeDeletedThemesInReview();renderProjects();enhanceThemeDeletion();renderRecurringRules();enhanceRecurringDeletion();renderHierarchyTree();renderHierarchyManagement();renderJournalCategoryManagement();renderRoutines();renderRoutineExecution();renderRoutineCategoryPicker();renderTodayOverview();renderPatrol();renderPatrolManage();renderPending();renderDeleted();renderSettings()}
async function addTask(value,source="manual",approvalStatus="approved",requestId=""){if(requestId&&db.importHistory.some(x=>x.requestId===requestId))return null;const task=Data.createTask({...value,source,approvalStatus,requestId,updatedBy:source==="ai"?"ai":"user"});db.tasks.push(task);if(requestId)db.importHistory.push({requestId,receivedAt:now()});await persist();return task}
async function actTask(target,action){const row=target.closest("[data-task-id]"),task=db.tasks.find(x=>x.id===row?.dataset.taskId);if(!task)return;const changes={},period=target.dataset.period;if(action==="star"&&period==="today")changes.todayDate=task.todayDate===currentDay()?null:currentDay();if(action==="star"&&period==="week")changes.weekStatusKey=isThisWeek(task)?null:currentWeek();if(action==="star"&&period==="month")changes.monthStatusKey=isThisMonth(task)?null:currentMonth();if(action==="complete")Object.assign(changes,{status:"done",completedAt:now(),todayDate:null});if(action==="delete")changes.deletedAt=now();if(action==="change-date"){const value=prompt("正しい完了日（YYYY-MM-DD）",taskDate(task));if(value&&/^\d{4}-\d{2}-\d{2}$/.test(value))changes.completedAt=value+"T12:00:00.000Z"}Data.updateTask(task,changes,"user");await persist();renderAll()}
function ensureName(kind,name){if(!name)return"";let item=db[kind].find(x=>isLive(x)&&x.name.toLowerCase()===name.trim().toLowerCase());if(!item){item={id:uid(),name:name.trim(),createdAt:now(),deletedAt:null};db[kind].push(item)}return item.id}
async function receiveAITasks(payload){const values=Array.isArray(payload)?payload:payload.tasks||[];let added=0;for(const [i,v] of values.entries()){if(!v.title?.trim())continue;const requestId=v.requestId||payload.requestId&&`${payload.requestId}:${i}`||"";const task=await addTask({title:v.title,description:v.description||"",categoryId:ensureName("categories",v.category),projectId:ensureName("projects",v.project),startDate:v.startDate||null,dueDate:v.dueDate||null,priority:v.priority||"none",estimateMinutes:Number.isInteger(v.estimateMinutes)?v.estimateMinutes:null,weekStatusKey:v.weekStatus?currentWeek():null,monthStatusKey:v.monthStatus?currentMonth():null},"ai","pending",requestId);if(task)added++}await persist();renderAll();return {received:added}}
async function receiveAIChanges(payload){const allowed=["categoryId","projectId","description","startDate","dueDate","priority","estimateMinutes","weekStatus","monthStatus"],changes=Array.isArray(payload)?payload:payload.changes||[];let added=0;for(const [i,v] of changes.entries()){const task=db.tasks.find(t=>t.id===v.taskId&&approved(t));if(!task||!allowed.includes(v.field))continue;const requestId=v.requestId||(!Array.isArray(payload)&&payload.requestId?`${payload.requestId}:${i}`:"");if(requestId&&db.importHistory.some(x=>x.requestId===requestId))continue;const requested=v.value??v.valueId??null,field=v.field==="weekStatus"?"weekStatusKey":v.field==="monthStatus"?"monthStatusKey":v.field,toValue=v.field==="weekStatus"?(requested?currentWeek():null):v.field==="monthStatus"?(requested?currentMonth():null):requested,fromValue=task[field]??null;db.aiChanges.push({id:uid(),taskId:task.id,field,fromValue,toValue,status:"pending",createdAt:now(),requestId});if(requestId)db.importHistory.push({requestId,receivedAt:now()});added++}await persist();renderAll();return {received:added}}
window.SimpleStepBridge={receiveAITasks,receiveAIChanges};

