function reconcilePeriodStatuses(){for(const task of db.tasks){const changes={};if(task.todayDate&&task.todayDate!==currentDay())changes.todayDate=null;if(task.weekStatusKey&&task.weekStatusKey!==currentWeek())changes.weekStatusKey=null;if(task.monthStatusKey&&task.monthStatusKey!==currentMonth())changes.monthStatusKey=null;if(Object.keys(changes).length)Data.updateTask(task,changes,"system")}}
